'pink-floral-case' => array('قاب باریک صورتی و زرشکی گل‌دار، فرمی باریک با ترکیب دو رنگ دارد.', 'کاربرد این قاب را با اندازهٔ وسیله‌ای که می‌خواهید داخل آن بگذارید تعیین کنید. پیش از سفارش، ابعاد داخلی و نوع بسته‌شدن را بپرسید و تناسب آن را برای همان وسیله تأیید کنید.'),
'pink-long-tab' => array('بند زبانه‌ای روی کیف پول چرمی بلند صورتی، یکی از جزئیات اصلی طراحی آن است.', 'در نمای بسته، فرم زبانه و محل قرارگیری آن را بررسی کنید. برای استفادهٔ روزمره، طول کیف و چیدمان داخلی را با تعداد کارت و مدارکی که حمل می‌کنید تطبیق دهید.'),
'burgundy-yellow-stitch' => array('دوخت زرد در کنار زمینهٔ زرشکی، ظاهر این کیف پول چرمی را مشخص می‌کند.', 'اگر دوخت با رنگ متفاوت از بدنه را می‌پسندید، این مدل را با نمونه‌های دارای دوخت هم‌رنگ مقایسه کنید. جزئیات داخل و شیوهٔ بسته‌شدن را برای نمونهٔ نهایی بررسی کنید.'),
'brown-organizer' => array('کیف دستی چرمی قهوه‌ای چندزیپ، با چند مسیر دسترسی زیپ‌دار معرفی می‌شود.', 'برای استفادهٔ روزمره، تعداد بخش‌هایی را که لازم دارید با چیدمان واقعی کیف مقایسه کنید. ابعاد هر بخش و شیوهٔ حمل را بپرسید تا انتخاب بر اساس وسایل خودتان انجام شود.'),
'tan-small-flap' => array('درِ گرد و رنگ عسلی، دو ویژگی مشخص این کیف پول چرمی کوچک هستند.', 'فرم لبهٔ گرد را در نمای بسته ببینید و آن را با مدل‌های دارای لبهٔ صاف مقایسه کنید. برای انتخاب کاربردی، ابعاد کیف و چیدمان کارت‌ها را هم بررسی کنید.'),
'black-curved-on-model' => array('کیف دوشی چرمی مشکی منحنی، با خط بدنهٔ نرم و رنگ مشکی معرفی شده است.', 'برای مقایسه با کیف‌های مربعی، به انحنای بدنه و محل اتصال بند توجه کنید. طول بند و ابعاد داخلی را برای همان مدل بپرسید تا شیوهٔ حمل با انتظار شما هماهنگ باشد.'),
'black-square-shoulder' => array('فرم مربعی و نشان طلایی، ظاهر این کیف دوشی چرمی مشکی را مشخص می‌کنند.', 'این مدل را از نظر خطوط بدنه و محل نشان با دیگر کیف‌های مشکی کاتالوگ مقایسه کنید. ابعاد فضای داخلی و طول بند، معیارهای تکمیل‌کنندهٔ انتخاب ظاهر هستند.'),
'black-tote' => array('کیف دستی چرمی مشکی دسته‌دار، با شیوهٔ حمل دستی معرفی می‌شود.', 'برای انتخاب کیف دسته‌دار، ارتفاع دسته و فاصلهٔ آن از بدنه را بررسی کنید. جاگرفتن وسایل مشخص مانند دفتر یا تلفن به اندازهٔ واقعی کیف بستگی دارد و باید برای همان مدل تأیید شود.'),
'cognac-pocket-shoulder' => array('جیب جلو، یکی از جزئیات قابل‌تشخیص کیف دوشی چرمی عسلی است.', 'اگر دسترسی جداگانه به بخشی از وسایل برایتان مهم است، ابعاد و نوع بسته‌شدن جیب جلو را بپرسید. اندازهٔ محفظهٔ اصلی و طول بند را نیز با شیوهٔ استفادهٔ روزانهٔ خود تطبیق دهید.'),
'gray-black-v-clasp' => array('قفل V و ترکیب طوسی و مشکی، هویت بصری این کیف دوشی چرمی را می‌سازند.', 'برای انتخاب این مدل، محل قرارگیری دو رنگ و فرم قفل را در عکس روبه‌رو بررسی کنید. نوع بازشدن قفل و طول بند را برای نمونهٔ نهایی با فروشگاه هماهنگ کنید.'),
'green-decorative-long' => array('کیف پول چرمی سبز با نقش تزئینی، رنگ سبز را با طرح رویه همراه کرده است.', 'نقش روی بدنه را در نمای نزدیک ببینید و آن را با مدل‌های سبز ساده مقایسه کنید. برای کاربرد روزانه، ابعاد نهایی و چیدمان داخل کیف را پیش از سفارش بررسی کنید.'),
'red-embossed-floral-set' => array('این ست، کیف پول چرمی و جاکارتی قرمز با گل برجسته را کنار هم معرفی می‌کند.', 'نقش گل و هماهنگی رنگ میان دو قطعه، بخش اصلی طراحی مجموعه است. ابعاد هر قطعه، ترکیب اقلام همراه و جزئیات نمونهٔ نهایی را پیش از سفارش تأیید کنید.'),
'brown-panel-clutch' => array('دوخت‌های عمودی، ظاهر این کیف دستی چرمی قهوه‌ای را مشخص می‌کنند.', 'جهت و فاصلهٔ دوخت‌ها را در نمای روبه‌رو ببینید؛ این جزئیات تفاوت آن با مدل‌های دارای رویهٔ کاملاً ساده است. برای انتخاب شیوهٔ استفاده، ابعاد و نوع بسته‌شدن را نیز بپرسید.'),
'brown-floral-zip-case' => array('کیف باریک قهوه‌ای زیپ‌دار با نقش گل، فرمی باریک و بسته‌شدن زیپی دارد.', 'برای تعیین کاربرد، اندازهٔ وسایلی را که می‌خواهید حمل کنید با ابعاد داخل کیف تطبیق دهید. در انتخاب ظاهر، نقش گل و رنگ زیپ را کنار زمینهٔ قهوه‌ای بررسی کنید.'),
'black-wide-strap-shoulder' => array('بند پهن، یکی از ویژگی‌های مشخص این کیف دوشی چرمی مشکی است.', 'برای انتخاب شیوهٔ حمل، عرض و طول بند و محل اتصال آن را بررسی کنید. میزان راحتی به اندازهٔ کیف و وزن وسایل شما هم بستگی دارد؛ ابعاد مدل نهایی را بپرسید.'),
'blue-coral-flower-wallet' => array('گل برجستهٔ مرجانی روی زمینهٔ آبی، نقطهٔ اصلی توجه در این کیف پول چرمی است.', 'برای مقایسه با دیگر مدل‌های گل‌دار، فرم گل و تضاد دو رنگ را در عکس نزدیک ببینید. ابعاد کیف و شیوهٔ بسته‌شدن را جدا از جزئیات تزئینی بررسی کنید.'),
'embroidered-cardholder' => array('جاکارتی چرمی گلدوزی‌شده، در نمونه‌های رنگی با دوخت دور و نقش گلدوزی معرفی شده است.', 'نمای باز مدل فیروزه‌ای، شیارهای کارت و آینهٔ داخلی را نشان می‌دهد. این جزئیات مربوط به همان نمونهٔ عکس هستند؛ چیدمان و رنگ جاکارتی انتخابی خود را پیش از سفارش تأیید کنید.'),
'woven-detail-cardholder' => array('تزیین بافتی و دوخت دور، ظاهر نمونه‌های سبز و صورتی این جاکارتی چرمی را مشخص می‌کنند.', 'برای انتخاب میان دو رنگ، عکس هر نمونه را جداگانه بررسی کنید. اگر جاکلیدی هماهنگ می‌خواهید، همراه‌بودن آن در ترکیب سفارش را با فروشگاه مشخص کنید.'),
'red-folding-cardholder' => array('جاکارتی چرمی تاشو قرمز و زرشکی، در نمای باز با شیارهای کارت و آینهٔ داخلی دیده می‌شود.', 'برای انتخاب بین دو نمونه، رنگ رویه و چیدمان بخش داخلی را مقایسه کنید. تعداد شیارهای موردنیاز و ابعاد مدل نهایی را متناسب با کارت‌هایی که حمل می‌کنید تأیید کنید.'),
'brown-wristlet-cardholder' => array('جاکارتی چرمی قهوه‌ای بنددار، شیار کارت در دو طرف، محفظهٔ زیپ‌دار و بند مچی دارد.', 'در نمای باز، فضای میانی برای قرارگرفتن تلفن نیز دیده می‌شود. سازگاری با تلفن شما به ابعاد دستگاه و قاب آن بستگی دارد؛ اندازهٔ فضای میانی را پیش از سفارش بررسی کنید.'),
);
